from __future__ import annotations
from .automated_benchmark import AutomatedBenchmarkCase
def t(name,rows):return {"name":name,"format":"records","rows":rows}
def build_logic_temporal_holdout(*,seed:int=20260927):
 if type(seed)is not int or not 0<=seed<=2**32-1:raise ValueError("holdout_seed_invalid")
 common={"family":"modeling_optimization","structure":"logical_resource_allocation_milp","objective_unit":"currency","direction":"maximize","integer_indices":[0,1,2,3],"tolerance":1e-8}
